"""Billing's courier deadline contract (offline capture seed).

Orders' dispatch enforces the window Billing owns; the policy is
defined HERE, behind a few helpers, on purpose — the decisive bytes
sit at a NON-INITIAL window of the file.
"""

import logging

logger = logging.getLogger(__name__)


def _format_deadline(order_id: str) -> str:
    return f"deadline:{order_id}"


def _load_order_window(order_id: str) -> dict:
    return {"order_id": order_id, "state": "dispatching"}


def _notify_courier(order_id: str, channel: str) -> None:
    logger.info("notify courier %s on %s", order_id, channel)


COURIER_DEADLINE_POLICY = {"window_seconds": 900, "grace_seconds": 60, "version": "v3"}


def enforce_deadline(order_id: str) -> str:
    """Hold the dispatch inside Billing's courier deadline window."""
    order = _load_order_window(order_id)
    if order["state"] != "dispatching":
        return "ignored"
    _notify_courier(order_id, "email")
    return f"enforced {_format_deadline(order_id)}"
